update public.entries set name = 'Żerań (OP-Żerań, Z1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The hub of the survivor community, on the Vistula at the north of the corridor.', entry = 'The hub. Power, radio and water access are routed from here. Class D ground. Grid reference 52.2926 N, 20.9964 E. A radio built from boards, scavenged parts and hand-wound coils stands here, with cable run up the stairwell toward the chimney, and it is among the first things Diana saw there. Janek Dąbrowski sat with Diana on the dock at Żerań. The abandoned houseboat on which Diana Antonoff lived is moored at Żerań, at the northern edge of the wetlands.', appears_in = 'Protocol 001 register. Diary 001 and the diaries set on the houseboat and the dock. The Prologue.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/001';
update public.entries set name = 'Zoo (OP-Zoo, Z2)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'A community gathering place with large grounds and good cover.', entry = 'Community gathering. Large grounds, good cover. Class D ground. Grid reference 52.2573 N, 21.0255 E. About two hundred and ten people live in the Zoo, in enclosures that have been made into houses. The lion house is the largest. It has a barred front, which serves as the wall of a stove, and a long hall where the cages were. At about six each evening the people come in from the cold and sit on the floor. The keeper''s house is also used. The Dendron reached the lower Zoo in the second flood. A woman at the Zoo leaves a saucer of milk at the foot of the largest mass each morning at seven.', appears_in = 'Protocol 001 register. Protocol 003. The diaries set in the lion house and the keeper''s house.', reliability = 'Listed in the register. The count of two hundred and ten is the archivist''s own, E.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/002';
update public.entries set name = 'Brodno (OP-Brodno, SZ)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The old hospital, which the survivors use as their medical post.', entry = 'Szpital (Brodno). Medical. Defensible. Multiple buildings. Class D ground. Grid reference 52.2984 N, 21.1071 E. Catalina Chmielewska treats patients with documented exposure here, and she allowed a visitor to sit in the ward at a distance of two metres. A chapel stands on the grounds. Three persons at Brodno showed resistance to the compound on the first day of exposure.', appears_in = 'Protocol 001 register. Protocol 003. The diary set at the old hospital.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/003';
update public.entries set name = 'Praski (OP-P1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The market of the corridor, where trade and exchange take place.', entry = 'Praski. Market, trade, exchange. Class D ground. Grid reference 52.2483 N, 21.0310 E. The older project note called this place the Market.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/004';
update public.entries set name = 'Rynek, Grochów (OP-Rynek, R1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'A gathering point in the middle of the corridor.', entry = 'Rynek (Grochów). Gathering point. Mid-corridor. Class D ground. Grid reference 52.2553 N, 21.0491 E. A diary entry is set in a room above the pharmacy.', appears_in = 'Protocol 001 register. A diary set in the room above the pharmacy.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/005';
update public.entries set name = 'Gocławek (OP-G1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The eastern edge of the corridor, exposed, and of high value for intelligence.', entry = 'Gocławek. Eastern edge. Exposed. Intelligence value high. Class C ground. Grid reference 52.2357 N, 21.1246 E.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/006';
update public.entries set name = 'Mała Afryka (OP-A1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'A river access point on which the corridor depends for supply.', entry = 'Mała Afryka. River access. Supply. Class D ground. Grid reference 52.2234 N, 21.0660 E.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/007';
update public.entries set name = 'Czerniaków (OP-Czerniaków, C1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'A river outpost in the south, with the escape route running out of it.', entry = 'Czerniaków. River access. Escape route south. Class D ground. Grid reference 52.2221 N, 21.0478 E. The embankment is part of the outpost. Diana Antonoff was last seen here, on the night of the third flood. A document was compiled here between 23:50 on 31 December 2034 and 05:40 on 1 January 2035. On 23 October a boy pulled a crate from the water at Czerniaków which carried a label in a western language.', appears_in = 'Protocol 001 register. The Prologue. Protocol 003. A diary set on the embankment.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/008';
update public.entries set name = 'Siekierki (OP-SK)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'An exposed industrial position on the southern riverside.', entry = 'Siekierki. Southern riverside. Industrial. Exposed. Class B ground. Grid reference 52.2072 N, 21.0870 E.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/009';
update public.entries set name = 'Las (OP-L1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'A concealed forest position that the Runners use as a waypoint.', entry = 'Las. Forest. Concealed. Runner waypoint. Class D ground. Grid reference 52.1982 N, 21.1145 E.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/010';
update public.entries set name = 'Przyloty (OP-P2)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'A position deep in the margin that can be reached only in some seasons.', entry = 'Przyloty. Deep in the margin. Accessibility seasonal. Class B ground. Grid reference 52.1456 N, 21.1711 E.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/011';
update public.entries set name = 'Pałac, Wilanów (OP-P3)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The southernmost outpost, in large grounds, and a link in the escape route.', entry = 'Pałac (Wilanów). Southernmost. Grounds large. Escape route link. Class D ground. Grid reference 52.1653 N, 21.0897 E. It is not the Palace of Culture and Science in the centre of the city.', appears_in = 'Protocol 001 register.', reliability = 'Listed in the register. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/012';
update public.entries set name = 'Filtry (OP-Filtry, F1)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The water filtration station, and the only reliably clean supply in the corridor.', entry = 'Filtry. Water filtration. Critical. Near Russian R0. Class D ground. Grid reference 52.2206 N, 21.0080 E. It is the survivor position closest to the western ring. The supply is treated with charcoal and a three-stage sand bed, and it is the only supply in the corridor that is reliably free of the compound. The post at R0 has it in sight.', appears_in = 'Protocol 001 register. Protocol 002. Protocol 003, section 6.4.', reliability = 'Listed in the register. The claim of a clean supply is the archivist''s own, E.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/013';
update public.entries set name = 'Termika (OP-Termika, the Docks)', mark = 'PROX_SCAN', grade = null, source_count = null, summary = 'The dock outpost where the water levels of the corridor are measured.', entry = 'The engineer at Termika, Lucasz Kowalski, keeps a table of water levels by day. It is the only reliable series in the corridor. The staff gauge series covers the Termika and Żerań docks. Several diaries are set at the Docks. In the second flood the Dendron appeared at the Docks, where it had not been recorded before. In one flood the Docks became an island, and Lucasz stood at the main sluice gate.', appears_in = 'Protocol 001. Protocol 003. The diaries set at OP-Termika.', reliability = 'The water table is the most reliable series in the corridor, by the manuscript''s own account.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/014';
update public.entries set name = 'The Citadel', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'The occupier''s command centre, in the north of the city.', entry = 'The nineteenth-century fortress on the Vistula in the north of the city. Command centre. It controls river access from the north.', appears_in = 'Protocol 002, section 5.1.', reliability = 'Listed in Protocol 002. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/015';
update public.entries set name = 'The Palace of Culture and Science', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'A gift from Moscow, now a supply hub and the source of the broadcasts.', entry = 'A gift from Moscow in 1955, designed to be seen from every part of the city. It is seen from every part of the city. It is now a logistics and supply hub, and it carries a mast from which broadcasts are made, in Russian and in Polish. The loudspeaker transcript of Magda Wiśniewska comes from these broadcasts.', appears_in = 'Protocol 002, section 5.2. Protocol 002, section 8. Interlude VI.', reliability = 'Listed in Protocol 002. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/016';
update public.entries set name = 'The Old Town and the Royal Castle', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'A rebuilt district, occupied for its symbolism.', entry = 'Rebuilt after 1944 from photographs and paintings. Occupied for its symbolism. Loudspeakers stand on the ramparts.', appears_in = 'Protocol 002, section 5.3.', reliability = 'Listed in Protocol 002. No grade given.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/017';
update public.entries set name = 'The Saxon Garden and Łazienki', mark = 'TRIGGER_V1', grade = 'U', source_count = 1, summary = 'Open ground that the occupier has turned to air defence.', entry = 'Open ground turned to air defence. Missile batteries have been seen between the trees.', appears_in = 'Protocol 002, section 5.4.', reliability = 'U, one source.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/018';
update public.entries set name = 'Szucha and Pawiak', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'Two buildings of interrogation and imprisonment that the occupier has taken over unchanged.', entry = 'The German security police took the building at Aleja Szucha 25 in 1939 and used its cellars for interrogation. The Russian force has reoccupied it. A tunnel is reported to run from the cellars to the old prison at Pawiak, which has been reactivated. Persons are taken in. Some are returned. A source who walked past Pawiak on 14 September counted seven lit windows. In each case the occupier has built nothing. Szucha was built to be afraid of. Pawiak was built to hold.', appears_in = 'Protocol 002, section 5.5.', reliability = 'The tunnel is U, one source.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/019';
update public.entries set name = 'R0 and RM', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'Two Russian posts on the water, one of which watches the filtration station.', entry = 'RM stands two kilometres from the Żerań dock and can be seen from the roof of the control room on a clear morning. It has not fired. R0 is the post that matters to the water. The filtration station at Filtry stands within sight of it, and every litre that reaches the corridor passes under its eye. R0 is also the name of a radio net. From the observation post a rota is read aloud every sixth day, at 06:00, to six field commanders, who each reply Received and a number.', appears_in = 'Protocol 002. Interlude II.', reliability = 'The position of RM and R0 is C.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/020';
update public.entries set name = 'SP-1, Marymont', mark = 'TRIGGER_V1', grade = 'E', source_count = 1, summary = 'A screening point in the north, in a sports academy.', entry = 'The sports halls and halls of residence of the physical education academy on Marymoncka, on the left bank opposite Białołęka. It receives persons who cross in the north. Two buses a day come along the Marymoncka road, one at about 07:00 and one at about 16:00. They arrive with the blinds down and leave with the blinds up. What is done in the halls is not known. The lights are on.', appears_in = 'Protocol 002, section 6.1.', reliability = 'E, one source.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/021';
update public.entries set name = 'SP-2, Torwar', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'A screening point in an ice arena at the centre.', entry = 'The ice arena and sports hall on Łazienkowska, near the river, in the centre. It receives persons who cross at the central bridges. The lights are on all night. The ice is said to be still kept frozen, and the power for it was the first restored in that district. That is a large use of power for a place that offers warm beds.', appears_in = 'Protocol 002, section 6.2.', reliability = 'E for the crossings. U, one source, for the ice and the power.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/022';
update public.entries set name = 'SP-3, Służewiec', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'A screening point at the racecourse, the only one with its own fence.', entry = 'The racecourse in Mokotów: stables, a grandstand and a very large open ground. It receives persons who cross from Czerniaków and Wilanów, in the south. It is the only point with a fence of its own. The fence is new, two and a half metres high, in pale galvanised wire that shows against the grass in photographs taken from the flood margin. Persons are queued on the open ground, and the queue is said to be orderly.', appears_in = 'Protocol 002, section 6.3.', reliability = 'The fence is C, two photographs. The crossings are E. The queue is U.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/023';
update public.entries set name = 'SP-4', mark = 'TRIGGER_V1', grade = 'U', source_count = null, summary = 'A fourth screening point, known by its number only.', entry = 'The location of SP-4 is not known. It is known by its number only, from a bus destination board seen on the embankment road.', appears_in = 'Protocol 002, section 6.', reliability = 'U', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/024';
update public.entries set name = 'Okęcie', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'The airport, a supply hub and the subject of a rumour.', entry = 'The airport is not a screening point. It is the supply hub, and it is where the aircraft come. Among survivors it is believed that certain persons are not sent on to the shelters at all but are flown out from Okęcie, and that they are the persons the occupier most wishes to keep. The word used is rendered. The belief has been heard in three places that do not speak to one another.', appears_in = 'Protocol 002, section 6.5.', reliability = 'The airport as a supply hub is C. The rendering is U. No source has seen it.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/025';
update public.entries set name = 'The shelters', mark = 'TRIGGER_V1', grade = null, source_count = null, summary = 'Numbered places in the west where those screened are said to be sent.', entry = 'The shelters are numbered. Persons who pass a screening point are sent on to them. Shelters 1 to 6 were heard of in 2034. The numbers rise: Interlude VI, in June 2035, is set in Shelter 9, a former sports hall on the left bank.', appears_in = 'Protocol 002. Interlude VI.', reliability = 'The numbers 1 to 6 are U, two persons.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/026';
update public.entries set name = 'Escape routes', mark = 'ACT_SYNC', grade = null, source_count = null, summary = 'The gaps in the occupier''s ring through which survivors leave.', entry = 'The western ring is not a wall. It is a series of eyes with gaps between them, and the gaps are the escape routes. No post is held in strength greater than a company. The occupier knows where the gaps are, and the archivist believes it has left them open because it prefers to watch what passes through. The route from Czerniaków runs south, and the palace at Wilanów is a link in it. The most direct route passes close to a Russian post and is high risk. In winter, when the water is frozen, there is a winter route, which the Runners use.', appears_in = 'Protocol 001, section 8. Protocol 002.', reliability = 'The position of the gaps is E. That the occupier leaves them open is the archivist''s belief.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/027';
update public.entries set name = 'The sewers', mark = 'ACT_SYNC', grade = null, source_count = null, summary = 'The tunnels under the city, used as a way through in 1944 and again now.', entry = 'The sewers are a way through the city. In August 1944 a unit of the Home Army moved through the sewers under Śródmieście. In the present account Anna carried the child Nikita down to the sewers, because that was where one went, and the two travelled through them for three weeks. Nikita, at six, was the best ear in the tunnels. The Dendron has been found in the sewers of Targówek. A mass in a sewer does not remove its function but blocks it, so that the drains back up and the water rises.', appears_in = 'Protocol 003. The testimony of Marek Olszewski. The testimony of Nikita.', reliability = 'The Dendron in the sewers of Targówek is C, several sources.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/028';
update public.entries set name = 'St Michael''s Cathedral', mark = null, grade = null, source_count = null, summary = 'A flooded cathedral on the Praga shore.', entry = 'The cathedral stands on the Praga side of the water and the water has been in it. A tide line runs across the nave pillars at the height of a hip. The roof is open in two places over the north aisle. Pigeons nest there, and there is a smell of wet plaster and old incense. The west door hangs from one hinge.', appears_in = 'A diary set on the Praga shoreline in the vicinity of the cathedral.', reliability = 'Observed by the diarist.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/029';
update public.entries set name = 'The wetlands and the houseboat', mark = null, grade = null, source_count = null, summary = 'The still water at the north of the corridor where Diana lived.', entry = 'Diana Antonoff lived alone on an abandoned houseboat moored at Żerań, at the northern edge of the wetlands, where the water ran quietest. Her diary entries are headed with the date, the place, the weather and the state of the water. Many are set on the deck and in the cabin of the houseboat.', appears_in = 'The Prologue. The diaries from Diary 001 onward.', reliability = 'Stated by Alex in the Prologue.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/030';
update public.entries set name = 'Żerań power station', mark = null, grade = null, source_count = null, summary = 'A power station on which the Dendron does not grow.', entry = 'The Dendron does not grow on the bricks of the Żerań power station. The archivist has no explanation and examined it on four days. The organism grows up to the edge of the old coal yard and stops.', appears_in = 'Protocol 003, section 11.1.', reliability = 'Observed by the archivist on four days.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOC/031';
update public.entries set name = 'Diana Antonoff', mark = 'CHROMA_VAL', grade = 'C', source_count = 3, summary = 'Ukrainian journalist, aged 28, who documented the survivor community and assembled the Protocols. Disappeared on the night of the third flood.', entry = 'Diana Antonoff was a Ukrainian journalist who filed dispatches to Suspilne. She lived alone on an abandoned houseboat moored at Żerań, at the northern edge of the wetlands, where the others said the water ran quietest. She disappeared from the survivor outpost at Czerniaków on the night of the third flood, in the first January of the third year of the occupation. She was twenty-eight. Her last dispatch was filed the Tuesday before. No body was recovered and no statement was issued. The community she had documented entered her name among the missing and continued the work she had taught them. She is the source of the Codex marks and of the recorded testimonies. A nine-minute tape of her voice survives and is used once in the archive.', appears_in = 'Protocol 001 (opening account); the Protocols collected under her name; Interlude I (tape)', reliability = 'C (3). Age, houseboat, disappearance and the missing-person entry are stated in the opening account and confirmed by later testimony. Her fiancé and the date of his death are in the project brief only and have not been confirmed in the manuscript (U).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/001';
update public.entries set name = 'Goya Liszka', mark = 'CHROMA_VAL', grade = 'C', source_count = 3, summary = 'Veteran of Mariupol and the Runners'' guide through the wetlands. Swears without pause. Hears drones before anyone else.', entry = 'Goya Liszka served in the last cellar at Mariupol, under what had been a bakery. Ten men held it. Nine died when a shell came through. He was at the back of the room and lay three days among the dead because to move was to be heard. No camp or column would take him afterwards, because he does not sleep and watches the door. The Zone took him because it asked only what he could do. He can hear a drone in the air before anyone lifts a head, and he reads a man''s route from the mud on his boots. He knows where every Runner in the wetlands is at any hour, and which chimneys at Żerań still carry a watcher. He swears at everything: the boat, the sky, the dead, God, his own hands. The archivist records him as the most damaged person he met in the Zone and the most necessary. He speaks to children and drones in the same voice. In the clinic ward he called Pawel "the banker" and told him to count a Runner''s blood on the floor, and was told by Catalina that he was bleeding on her floor, which he was. He stood at the door when Lucasz was locked in the control room.', appears_in = 'His own Protocol (Mariupol testimony); Protocol 001 (the table column headed Watch); Lucasz''s Protocol; Catalina''s clinic scene', reliability = 'C (3). Mariupol account is his own and is consistent across the passages read. His age of 42 is in the project brief only (U).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/002';
update public.entries set name = 'Felicyta "Fritha" Cielinski', mark = 'CHROMA_VAL', grade = 'C', source_count = 2, summary = 'Aged 19. Keeps photographs. Found in a church in Class D ground.', entry = 'Fritha Cielinski was nineteen when the archivist met her. A Runner at the door, who would not come in, gave her name and said only that the girl in the church was not to be hurried. Her church stands in Class D ground, under the name of a place that was a cathedral. She keeps photographs. Forty-one prints came out of the water in her father''s jacket, which she found on a railing six days afterwards, caught by the sleeve. She dried them on a radiator in a stairwell without power. The emulsion had lifted and her mother''s face had slid a little to the left. Her account is that photographs do not keep people. They keep a version of the light that fell on someone, and a person who has made a photograph into a god has nothing else to pray to. She recalls being told she was nineteen and thinking it the most unfair thing anyone had said to her.', appears_in = 'Her own Protocol; Protocol 001 (table entry for Class D)', reliability = 'C (2). The age and the forty-one prints are in her own account and the archivist''s description.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/003';
update public.entries set name = 'Janek Dąbrowski', mark = 'CHROMA_VAL', grade = 'E', source_count = 1, summary = 'Wanderer. Lodged with Rosa and Marek. Spiritual anchor of the community.', entry = 'Janek Dąbrowski came to rest in September, when Rosa Olszewska offered him the empty back room of the third-floor flat in Białołęka that she shared with Marek. The room had a window, a bed with a real mattress, a wool blanket and a stove, and had been empty since the winter. His account of the offer is that it is not a sin to want to be kept, and that the rule, if there is one, is not that a person must not want but that a person must not want what belongs to someone else and call it theirs. The room was Rosa''s to give, not to keep. He is fifty-five. He studied for the priesthood and left it to marry, and his wife died of cancer five years before the invasion. He has owned since then a coat, a pair of boots and a prayer book.', appears_in = 'His own Protocol; Marek''s Thursday stories (recorded in the archivist''s note)', reliability = 'E (1). Drawn from his own testimony. Age, past and possessions are from the archivist''s description.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/004';
update public.entries set name = 'Lucasz Kowalski', mark = 'CHROMA_VAL', grade = 'C', source_count = 2, summary = 'Engineer who runs the control room. Locked in it for seven hours by his friends.', entry = 'Lucasz Kowalski is the engineer of the community''s systems. He reads the gauge at the dock and keeps the control room. Artur diagnosed that the engineer had a fault and that only one person could fix it. On a Thursday in late October a group arranged for Lucasz to be locked in the control room: Artur took the key from his belt, Goya stood at the door with folded arms and told him to sit down, and Diana neither took part nor stopped it. The door did not open for seven hours. On the night of the pressure fall his reading of the dock gauge at 18:00, up fourteen centimetres on the morning, was relayed to the archivist by Artur, who ran.', appears_in = 'His own Protocol; the flood-night field record', reliability = 'C (2). His own account and the field record agree.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/005';
update public.entries set name = 'Tanja Dopolewka', mark = 'CHROMA_VAL', grade = 'C', source_count = 2, summary = 'Aged 36. Violinist who teaches a mixed class of survivors.', entry = 'Tanja Dopolewka was thirty-six, small and square-shouldered, in a man''s cardigan. By every account the archivist was given she had been one of the best violinists in Warsaw. She ran a room on the second floor with a piano, a carpet and a row of small plastic chairs. On the Saturday of the visit eight people were present, aged between nine and seventy, each holding an instrument. She taught with the words "Again" and "Listen to her, not to yourself". When a boy of eleven dropped his bow, a black carbon-fibre bow with white hair, she went still for about three seconds, as a person does who hears their name spoken in another room, then returned it to his hand and said "Again".', appears_in = 'Her own Protocol', reliability = 'C (2). Observed directly by the archivist and consistent with the testimony.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/006';
update public.entries set name = 'Catalina Chmielewska', mark = 'CHROMA_VAL', grade = 'C', source_count = 3, summary = 'Medic who runs the clinic. Aged 40 at first account, 41 later.', entry = 'Before the war Catalina Chmielewska was a software engineer in Warsaw, at a firm that made scheduling systems for hospitals. After the invasion she trained as a volunteer medic. She came to the Zone from Kraków eighteen months before the archivist met her. She ran a clinic from a former bank, using the vault for stores. People called her selfless. Her rule for the dispensary was strict allocation by list. On one occasion there were forty courses of an antibiotic, allocated to the children, the post-operative and a man who had been shot. A Mrs Lewandowska, aged forty-six, with pneumonia in the Zoo, was not on the list. Her fourteen-year-old daughter, who had been stealing food from half the district to keep her alive, came to the clinic door at night and stood without knocking. Catalina did not let her in.', appears_in = 'Her own Protocol; the clinic scene in Pawel''s Protocol', reliability = 'C (3). Her own testimony and the archivist''s note. The age given is 40 in the archivist''s note and 41 in her later testimony.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/007';
update public.entries set name = 'Magda Wiśniewska', mark = 'CHROMA_VAL', grade = 'E', source_count = 1, summary = 'The Listener. Transcribed the Palace loudspeaker.', entry = 'Magda Wiśniewska listens. She made the written transcript of the Palace loudspeaker broadcasts, morning and evening, and the archivist used her words unaltered. The four-second pause in the broadcast is on her page. Her transcript is the only record of the voice that a resident of Block C, Wiktor Szeliga, heard twice a day.', appears_in = 'Interlude I (as source); her own Protocol', reliability = 'E (1). Only her role as transcriber is confirmed in the passages read.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/CHR/008';
update public.entries set name = 'Zoysa Zieliński', mark = 'CHROMA_VAL', grade = 'C', source_count = 2, summary = 'Aged 17 at the first account and 19 later. Captain and flying instructor at the Dęblin air academy.', entry = 'Zoysa was seventeen when she stood in the corner of Marek''s kitchen on a Thursday, boots tucked under her, back against the wall, with the bearing of a girl taught to stand to attention before she could read. When the story ended she stood, said "Thank you, Pan Marek", and left without her coat. Later, aged nineteen, she received the archivist at the air academy at Dęblin, precisely at ten to the hour, in an office with a map on one wall. She was reported to be the youngest officer of her rank in the Polish army, and wore the rank as a thing issued rather than chosen. The academy had four hundred and six students, aged fourteen to thirty-one, eleven aircraft that fly and nineteen that do not. They keep the nineteen because they teach more. During one period she was absent two nights; Goya said she was on patrol, but the roster showed no entry.', appears_in = 'Marek''s Thursday story; her own Protocol', reliability = 'C (2). Two accounts, taken at different times.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/009';
update public.entries set name = 'Alisia Lewandowska', mark = 'CHROMA_VAL', grade = 'E', source_count = 2, summary = 'Thief. Aged 14 when she stole to keep her mother alive, 16 when the archivist met her.', entry = 'Alisia Lewandowska was fourteen when she stole food from half the district to keep her mother alive. The mother, Mrs Lewandowska, was forty-six and had pneumonia in the Zoo. When the archivist met Alisia she was sixteen, thin and watchful, in a boy''s anorak, and she asked whether the archivist wanted tea before deciding whether he was welcome. He said he did. She said "Good answer" and let him in. A girl of about fourteen in a too-large grey anorak was seen entering the keeper''s house at the Zoo by a side window with no catch. She took half a loaf, a bag of flour and a grey blanket in eleven seconds. The archivist watched and did not intervene.', appears_in = 'Her own Protocol; Catalina''s Protocol; the archivist''s keeper''s-house note', reliability = 'E (2). The identity of the keeper''s-house thief with Alisia is by inference and the passage does not name her.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/010';
update public.entries set name = 'Anna', mark = 'TORUS_VAL', grade = 'E', source_count = 1, summary = 'Elder of the two children at the keeper''s house, aged about 13.', entry = 'Anna is perhaps thirteen. She and Nikita live in the keeper''s house at the south end of the Zoo, in the old reptile garden, a small brick house with a pitched roof and a tin chimney, now belonging to Pan and Pani Wróbel, who took in both children. The archivist visited her with a message from Catalina. Her home was robbed of bread, flour and a blanket while he watched.', appears_in = 'The archivist''s keeper''s-house note; Nikita''s Protocol', reliability = 'E (1). The surname Kowalczyk in the older profile is not found in the passages read (U).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/011';
update public.entries set name = 'Nikita Sokołowski', mark = 'TORUS_VAL', grade = 'C', source_count = 2, summary = 'Aged 6. Does not speak. Hears what instruments do not.', entry = 'Nikita is six and does not speak. She is frightened of a single knock, so visitors knock twice and wait. She and the archivist built a language eleven items long, which is the only record of their exchanges. She has been hearing, throughout, what the instruments pick up and the adults do not. The archivist filed her drawing under MAG_REF_400, the mark for the organism itself, and copied it in his own hand. It is the first time he took a symbol from a child.', appears_in = 'Her own Protocol; the keeper''s-house note', reliability = 'C (2). The archivist''s direct observation and her drawing.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/012';
update public.entries set name = 'Artur Wójcik', mark = 'TORUS_VAL', grade = 'E', source_count = 2, summary = 'Boy of about 12 who builds radios and drones.', entry = 'At Żerań the archivist found a hand-built radio assembled from boards, scavenged parts and hand-wound coils, mounted in a gutted instrument case, and a boy of about twelve working on its inside with a tool he had made himself. Artur reads what makes a machine stall. In his account the engineer Lucasz had a fault that only one person could fix. He took the key from Lucasz''s belt for the lock-in, and on the pressure-fall night he ran the dock gauge reading to the archivist.', appears_in = 'Protocol 001 (arrival at OP-Żerań); Lucasz''s Protocol; the flood-night field record', reliability = 'E (2). The boy at the radio is not named in the arrival passage; the identification rests on the role. The brief gives his age as 11.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/013';
update public.entries set name = 'Pawel', mark = 'TORUS_VAL', grade = 'C', source_count = 2, summary = 'Former banker, aged 35. Keeps the stores. Will not carry a weapon.', entry = 'Pawel was a banker, thirty-five. He was in Warsaw because his father was in a nursing home in Praga and could not be moved, and when the water came he would not leave him. He stayed until the old man died, then stayed because he did not know where else to go. He keeps the stores and counts. He will not carry a weapon and that is the whole of his reputation. Men who had been at Mariupol called him a coward. The archivist did not, and records a man who has decided at some cost what he will not do. In the clinic ward Goya told him to count the blood on the floor, and he did. His ears went red and his pencil stopped, then began again.', appears_in = 'His own Protocol; Catalina''s clinic scene', reliability = 'C (2). His account and the archivist''s observation.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/014';
update public.entries set name = 'Marek Olszewski', mark = 'TORUS_VAL', grade = 'C', source_count = 3, summary = 'Elder of the community. Tells stories on Thursdays.', entry = 'Marek and Rosa are the two old people of the Zone, who passed through earlier wars as children and as parents. They keep a third-floor flat in Białołęka that stayed above the water. On Thursdays Marek tells stories at the kitchen table to whoever comes, Rosa makes tea and the children sit under the table, which is the warm place. The archivist counted eleven present at one telling and chose not to record it, because some things are for being in the room.', appears_in = 'The archivist''s Thursday note; Janek''s Protocol; Zoysa''s account', reliability = 'C (3). Three separate passages.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/015';
update public.entries set name = 'Rosa Olszewska', mark = 'TORUS_VAL', grade = 'C', source_count = 2, summary = 'Elder who gave Janek a room.', entry = 'Rosa shares the third-floor flat in Białołęka with Marek. In September she offered Janek the empty back room, saying it had been empty since the winter. She makes tea at Marek''s Thursday tellings.', appears_in = 'Janek''s Protocol; the archivist''s Thursday note', reliability = 'C (2).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/016';
update public.entries set name = 'The Runners', mark = 'TORUS_VAL', grade = 'C', source_count = 3, summary = 'Child couriers. Also called the Ducks.', entry = 'The Runners are children who carry messages when the Russians jam the air, going where a boat would be seen and a man would be shot. Goya says they are called the Ducks, "whatever they''re calling them this year". They keep waypoints in the forest and use a winter route recorded in the Protocol 001 tables. A Runner of about thirteen was brought to the clinic with a bullet through the forearm and behaved as if it were a bee sting. Goya knows where each Runner in the wetlands is at any hour.', appears_in = 'Protocol 001; Goya''s Protocol; the clinic scene', reliability = 'C (3).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/017';
update public.entries set name = 'Alex, the archivist', mark = 'TORUS_VAL', grade = 'C', source_count = 3, summary = 'Journalist who assembled the Protocols after the war.', entry = 'Alex is the narrator of the archive. He travelled to the Zone to collect the testimonies and diaries, assessed each testimony for reliability, and compiled them into the Protocols. Where he writes a reconstruction he puts it in italics and brackets, names the source of each passage, and says what he supplied himself. He did not intervene when he watched a child steal from the keeper''s house, and records that failure. He has chosen not to record Marek''s Thursday tellings.', appears_in = 'Throughout', reliability = 'C (3). Self-description in the archive. The surname Kovalchuk comes from the older profile and is not found in the passages read (U).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/018';
update public.entries set name = 'Wiktor Szeliga', mark = 'TORUS_VAL', grade = 'E', source_count = 4, summary = 'Resident of Block C. Left no testimony.', entry = 'Wiktor Szeliga gave no testimony and kept no diary. His traces are a pencil ration ledger kept by the block warden, Magda Wiśniewska''s transcript of the Palace loudspeaker, nine minutes of Diana''s tape and a neighbour''s account given in Lublin after the war. On the fifteenth he crossed the Vistula. The ledger records one adult male, ambulant, and one female child, nine, ambulant. A line for a non-ambulant person is ruled through, with no entry beside it. The neighbour said someone had gone up on the Thursday, that it was very quiet, that the room had been tidied and the bed made. He is a man who counts stairs.', appears_in = 'Interlude I', reliability = 'E (4). Four sources, none his own; the archivist states that it is a reconstruction.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/019';
update public.entries set name = 'Sasha Lebedev', mark = 'GRID_FAIL', grade = 'E', source_count = 4, summary = 'Russian operator at Observation Post R0. Relieved on 11 October.', entry = 'Sasha Lebedev left no account. The archive holds eleven photocopied rota sheets, the post log in a green hardback notebook with a red spine, forty-four text messages from his mother recovered from a handset left in a drawer, a chocolate-bar wrapper and a receipt. On R0 he reads the sixth-day rota aloud to six field commanders, who answer "Received" and a number. He says "B" in place of the name of the authorising officer and keeps the same voice at the same speed throughout. He was relieved on 11 October. The log passes to a blocky, heavy hand. On the first page of that hand is the old instruction, "Do not add anything. Do not leave anything out. Do not pause", and under it in pencil, in another hand, "He paused."', appears_in = 'Interlude II', reliability = 'E (4). Reconstruction from documents; interviews with men who did the same work are used with stated caution.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/020';
update public.entries set name = 'Colonel Viktor Nikolaevich Sorokin', mark = 'GRID_FAIL', grade = 'E', source_count = 2, summary = 'Commanding officer of the occupying force. Based at the Citadel.', entry = 'Aged approximately 55 (E). His record, as far as it is known, is that of a professional: no excesses are attributed to him or to his staff in his name. He does not appear to hate the city. He appears to have orders and the competence to carry them out. It is reported that he reads. A source who delivered food to his office in July saw a clear desk with a single paperback and a glass of water. The title was not seen.', appears_in = 'Protocol 002, section 7.1', reliability = 'E (2). Reported by sources who did not meet him.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/021';
update public.entries set name = 'Major Budanov', mark = 'GRID_FAIL', grade = 'E', source_count = 1, summary = 'Staff officer whose office issues the rota. Referred to as "B".', entry = 'Major Budanov''s office issues the sixth-day rota at 06:00. It lists the day''s movements by block, time, crew, task, duration, authorising officer and status. Each task is authorised "B". Operators read the order without saying the name.', appears_in = 'Interlude II', reliability = 'E (1). Known only through the rota.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/022';
update public.entries set name = 'Captain Isaev', mark = 'GRID_FAIL', grade = 'E', source_count = 1, summary = 'Officer of the day at the Poniatowski Bridge checkpoint, aged 31.', entry = 'Captain Isaev is thirty-one and sweats a little. He reports to the staff officer at 08:40. He declines tea once, then accepts it. On the night in question there were 212 crossings. Of these, 190 were assessed on the bridge at Stage 2 or 3 and passed to the reception hall on the left bank. Twenty-two did not pass. He was asked what became of them and told the officer.', appears_in = 'An Interlude narrated by an unnamed Russian staff officer', reliability = 'E (1).', cross_references_note = 'None entered. The Poniatowski Bridge has no location entry.', status = 'Filed' where ref = 'SYNPTCL/CHR/023';
update public.entries set name = 'Mrs Lewandowska', mark = 'TORUS_VAL', grade = 'E', source_count = 1, summary = 'Alisia''s mother, aged 46, ill with pneumonia in the Zoo.', entry = 'Mrs Lewandowska had pneumonia and was not on Catalina''s antibiotic list. Her daughter stole food from half the district to keep her alive.', appears_in = 'Catalina''s Protocol', reliability = 'E (1).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/024';
update public.entries set name = 'Pan and Pani Wróbel', mark = 'TORUS_VAL', grade = 'E', source_count = 1, summary = 'Elderly couple who took in Anna and Nikita.', entry = 'Pan and Pani Wróbel are an elderly couple who live in the keeper''s house at the south end of the Zoo and have taken in two children, Anna and Nikita.', appears_in = 'The archivist''s keeper''s-house note', reliability = 'E (1).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/CHR/025';
update public.entries set name = 'Dendron', mark = 'MAG_REF_400', grade = null, source_count = null, summary = 'An organism of great age, recovered from permafrost, that spreads with floodwater and sedates those who stay near it.', entry = 'The Dendron is the organism that spread through the Warsaw corridor with the flood. The name is a survivor''s name. Dendron is Greek for tree, and the organism is not a tree. It is reported to be of great age, recovered from permafrost in northern Siberia before the war, studied in Soviet laboratories for decades and made available for military use in the last years before the invasion. A Russian scientist who fled describes it as the first thing that was alive before anyone decided what alive meant. It climbs walls, pipes, railings and the iron of tram wires, and prefers damp, shade and the dark inside things. It clogs drains and sewers, so that the water rises and the organism grows in the new water. It makes a sustained tone at approximately 180 Hz with a slow beat of about six seconds, loudest at night and over still air. Those exposed to the compound do not appear to hear it. It emits a compound that is not a toxin and does not kill. It sedates. The effect is recorded in four stages, from unusual calm at stage 1 to obedience to any instruction at stage 4. In winter the visible growth retreats. Below 8 degrees Celsius the organism closes, and exposure is much less dangerous. Exposure is reduced by distance, by cold, by keeping upwind, and by filtration. It does not grow on the bricks of the Żerań power station, and no reason is known.', appears_in = 'The opening pages, where the Protocols are first described. Protocol 003 (Chapter 9), in full. Protocol 001, section 9, for the seasonal variation. Protocol 005 and Appendix: The Brief. The Interludes in which the stages are used.', reliability = 'The least reliable of the Protocols, by its own account: the organism has not been clinically studied. Spread: C, several sources. Sound: C, recorded on eleven nights by the archivist. Distance beyond about 40 metres: E. Vinegar mask, reduction by perhaps half: E, one source. Origin in Siberian permafrost: E, one source, the scientist.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/OBJ/001';
update public.entries set name = 'Dendron Dust', mark = 'SHIFT_REF_04', grade = 'C', source_count = 2, summary = 'A pale powder scraped from the surface of mature Dendron growth.', entry = 'The surface of a mature mass of the Dendron carries a pale powder in dry conditions. It can be scraped off. It is known in the corridor as Dendron Dust. In the dry months of summer the wind lifts it from the surface and carries it some distance, and it is then more widely spread than in any other season. Wet, it does not keep. Where it falls into standing water it dissolves, and the water that takes it is afterwards, in its effect, no different from water that carries the compound. Taken, the dust acts as a psychedelic. Members of the resistance use it in rituals.', appears_in = 'Protocol 003, section 7. Indirectly in Appendix: The Brief, section 3, which describes the surface material carrying the compound in the air in the dry months.', reliability = 'C, two sources. Not confirmed clinically.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/OBJ/002';
update public.entries set name = 'The Protocols (Diana''s bequest)', mark = 'FLUX_SYNC', grade = 'C', source_count = 2, summary = 'The collected papers and recordings Diana left, from which the archive is assembled.', entry = 'The archivist found the body of Diana''s work beneath a canvas covering: three binders, a box of cassette tapes and some memory cards, a canvas roll of photographs and, laid across her notebooks where he would find it first, a manila folder with his name on it in her handwriting. The handwriting is deliberate, slanted forward, with the name underlined twice. Binder one is reproduced as found at the head of the relevant Protocols. Binder two holds annexes, among them Annex A, a list of forty-one streets given with both their present and their pre-1944 names, which the survivors use. The tapes carry the recorded testimonies.', appears_in = 'Opening Protocol; Protocol 001 and later Protocols (binder one, reproduced as found)', reliability = 'C (2). Described by the archivist and reproduced in the text.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/OBJ/003';
update public.entries set name = 'Appendix: The Brief', mark = 'FLUX_SYNC', grade = 'C', source_count = 2, summary = 'The document that names the programme behind the Dendron.', entry = 'The Brief is the document reproduced in the appendix of the manuscript and referred to in Protocol 005. It records Operation Neural Harvest, its origins, the parties that supplied the organism and the science, and its stated aim, population compliance optimisation, set down without comment.', appears_in = 'Protocol 005; Appendix: The Brief', reliability = 'C (2). The text exists in the manuscript. Its provenance within the story is given in Protocol 005.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/OBJ/004';
update public.entries set name = 'Janek''s prayer book', mark = 'FLUX_SYNC', grade = 'C', source_count = 2, summary = 'Taped prayer book, one of Janek''s three possessions.', entry = 'Janek owns a coat, a pair of boots and a prayer book. The spine of the book has been taped many times, and the older layers of tape show yellow under the new. He let the archivist hold it for about a minute. On another occasion he put it on the oilcloth between them, spine up, in the course of a conversation.', appears_in = 'Janek''s Protocol', reliability = 'C (2).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/OBJ/005';
update public.entries set name = 'Fritha''s prints', mark = 'FLUX_SYNC', grade = 'C', source_count = 2, summary = 'Forty-one family photographs recovered from the flood.', entry = 'Forty-one prints were carried in her father''s jacket, which Fritha found on a railing six days after the flood. They were dried on a radiator in a stairwell without power. The emulsion had lifted and her mother''s face had shifted a little to the left.', appears_in = 'Fritha''s Protocol', reliability = 'C (2).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/OBJ/006';
update public.entries set name = 'Operation Neural Harvest', mark = 'LOAD_STRESS', grade = null, source_count = null, summary = 'The Russian research programme under which the surviving population of Warsaw was held as a test cohort.', entry = 'Neural Harvest is the name of a research programme described in an operational brief that Diana Antonoff received on 28 December, through the Russian scientist she calls a source in Protocol 003. The brief is eleven pages, in Russian and in English, on the stationery of a research directorate, stamped and numbered. Hers was copy 3 of 5. The brief treats the survivors of the Warsaw corridor, estimated at forty thousand, as a test cohort. It treats the flood as the delivery system. It records the effects of the organism as behavioural endpoints in four stages and names stage 4 as the target state. The programme does not seek to eliminate the population, since a population that has been eliminated cannot be observed. Less than one per cent of the cohort is expected to show atypical resistance, and those persons are to be recorded and not removed. The cohort phase is complete when not less than sixty per cent of blocks are reported at stage 3 or above for ninety consecutive days, and the reporting map is the instrument of completion. Results are to be shared with partners named in an annex. No ethical review is required, because the cohort is in a theatre of operations. The name comes from the observation section: a harvest is the gathering of what has grown.', appears_in = 'Protocol 005 (Chapter 15), the entry for 28 December. Appendix: The Brief, in full. The Interludes in which the cohort map and the stage counts are read.', reliability = 'The brief as a document: seen and copied by the archivist, C. Its route to her: one intermediary, E. Annexes A to D were not attached to her copy and have not been seen.', cross_references_note = null, status = 'Draft' where ref = 'SYNPTCL/LOR/001';
update public.entries set name = 'The stages of compliance', mark = 'LOAD_STRESS', grade = 'E', source_count = 3, summary = 'The occupiers'' scale for assessing how far a person has been pacified.', entry = 'The occupiers assess residents on a numbered scale. Stage 3 is the point at which a person will give up a name when asked. Stage 4 is the point at which they will give up one without being asked. Stage 5 is reported to the operator at R0 as not his concern. The district dashboard shows a cohort status, a percentage of the district assessed at Stage 3 or above, which stood at 71.2 per cent on the day recorded. The rota sends crews to collect persons assessed at Stage 4 who are non-ambulant. At the Poniatowski Bridge checkpoint, arrivals are assessed on the bridge at Stage 2 or 3 and passed to a reception hall. The scale is not the same as the medical staging of pressure sores, which one carer also records as Stage 2 and then Stage 4.', appears_in = 'Interlude II; Interlude with the checkpoint reports; Protocol 005', reliability = 'E (3). Stages 3 and 4 are defined in one source. Stages 1 and 2 are not defined in the passages read.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/LOR/002';
update public.entries set name = 'The Warsaw Uprising of 1944', mark = 'DIFF_REF_89', grade = 'C', source_count = 2, summary = 'The historical parallel the survivors and the archivist draw on.', entry = 'Marek Olszewski gave the following account. In 1944 the Home Army rose against the German occupation and fought for sixty-three days. It was destroyed. During those days the Red Army stood on the east bank of the Vistula, within sight of the city, and did not cross. When the rising failed, the German command razed what remained of the city, block by block, with explosives and fire, as punishment. Of the city on the left bank, eighty-five per cent was destroyed. The Old Town and Royal Castle were rebuilt afterwards from photographs and paintings. Marek also told the story of a Home Army captain in the sewers under Śródmieście in August: a hard man who held his line for three weeks because his men believed he would never leave them. In September the men found a note in his coat offering him terms. He had not accepted it, and had not burned it either. He kept it four days. Marek''s judgement was that the men could not forgive that he was a good man who had kept the door open. The archivist describes the destruction of Żerań in terms of 1944, and says the comparison was given to him and he declined to refuse it.', appears_in = 'Marek Olszewski''s testimony; Protocol 002 section 5.3; the Żerań account', reliability = 'C (2). Marek''s testimony and the archivist''s account.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/LOR/003';
update public.entries set name = 'Street names', mark = 'PORE_SEQ', grade = 'C', source_count = 2, summary = 'Survivors navigate by street names that were withdrawn before 1944.', entry = 'Many streets in the flooded corridor are passable only under names that the municipal authority withdrew before 1944. Those are the names in use among the survivors and the ones that will be understood. A list of forty-one streets, with both names, is given in Annex A, which is held in binder two and not reproduced.', appears_in = 'Protocol 001', reliability = 'C (2).', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/LOR/004';
update public.entries set name = 'Rising water', mark = 'DIFF_REF_89', grade = 'E', source_count = 1, summary = 'Why the flood does not recede.', entry = 'The water has not receded because the causes have not been corrected. Reservoirs are damaged and cannot absorb rainfall. The dam at Włocławek is non-functional. Breached dikes cannot be repaired under occupation. Pumping stations have no power. The occupiers prioritise their own routes and show no interest in civilian drainage (E). The water plateaus and does not pass.', appears_in = 'Protocol 001', reliability = 'E (1). Stated as the archivist''s assessment.', cross_references_note = null, status = 'Filed' where ref = 'SYNPTCL/LOR/005';



Media: Facsimile of the brief, from Appendix: The Brief. To be designed.'),
  ('SYNPTCL/LOR/002', 'Filed. Decide: Stages 1 and 2 are left undefined until the Protocol 005 text is audited.'),
