insert into public.editor_notes (ref, note) values
  ('SYNPTCL/LOC/004', 'Draft. The manuscript says little. The older Market file is merged into this entry.'),
  ('SYNPTCL/LOC/014', 'Draft. Termika is not in the register table. The older file called it a canal dock, which the manuscript does not support.'),
  ('SYNPTCL/LOC/016', 'Draft. Whether the Palace is the source of the loudspeaker in Interlude VI should be checked.'),
  ('SYNPTCL/LOC/019', 'Draft. The older files list these as Gestapo HQ and Pawiak Prison, and they are merged here.'),
  ('SYNPTCL/LOC/024', 'Draft. Written from the project''s screening points file. Section 6.4 of Protocol 002 should be checked against it.'),
  ('SYNPTCL/LOC/026', 'Draft. Written from the project''s screening points file. Needs checking against Interlude VI.'),
  ('SYNPTCL/LOC/027', 'Draft. The older file The Land Beyond is not found in the manuscript and is held as reference only.'),
  ('SYNPTCL/LOC/028', 'Draft. Whose testimony carries each account should be confirmed.'),
  ('SYNPTCL/LOC/029', 'Draft. Alex says that Fritha''s church is listed in Class D under the name of a place that was a cathedral. This may be that building, but the manuscript does not say so.'),
  ('SYNPTCL/LOC/030', 'Draft. The older files list the Wetlands and the Docks as separate places. The Docks are covered under Termika.'),
  ('SYNPTCL/CHR/001', 'Filed. Decide: the manuscript records her as disappeared, not dead; the entry follows it. Check the fiancé detail against the manuscript before release.'),
  ('SYNPTCL/CHR/002', 'Filed. The older profile describes him as commander of field operations; the manuscript passages read show him as guide and watcher. Decide: kept to the manuscript.'),
  ('SYNPTCL/CHR/003', 'Filed. Decide: the church is linked to LOC/029 (St Michael''s Cathedral) on the strength of the Protocol 001 note; confirm at audit.'),
  ('SYNPTCL/CHR/004', 'Filed in short form. Decide: the older profile gives details not found in the manuscript passages read; they are left out until confirmed.'),
  ('SYNPTCL/CHR/005', 'Filed. The location of the control room is not given in the passages read, so no LOC reference is entered.'),
  ('SYNPTCL/CHR/006', 'Filed. The location of the room is not given in the passage read. The meaning of the bow is left to her Protocol.'),
  ('SYNPTCL/CHR/007', 'Filed. A secret relationship is part of her planned arc and is in the project brief; it has not been confirmed in the passages read (U). Outcome for Mrs Lewandowska not confirmed in the passages read.'),
  ('SYNPTCL/CHR/008', 'Short entry. Her own Protocol has not yet been read for this entry. Decide: expanded in the audit pass.'),
  ('SYNPTCL/CHR/009', 'Filed. The older profile gives her age as 17 only and describes her as male in one place. The manuscript gives both ages and a female captain. Decide: the manuscript is followed.'),
  ('SYNPTCL/CHR/010', 'Filed. Decide: the manuscript gives two ages because the accounts were taken at different times; both are kept.'),
  ('SYNPTCL/CHR/011', 'Filed. Her part in the sewers is left to be confirmed.'),
  ('SYNPTCL/CHR/012', 'Filed. Decide: surname spelled as in the project brief. The feminine form Sokołowska would be usual in Polish; flagged for the author.'),
  ('SYNPTCL/CHR/013', 'Filed. Decide: age kept as "about 12" to match the manuscript.'),
  ('SYNPTCL/CHR/014', 'Filed. No surname given in the passages read.'),
  ('SYNPTCL/CHR/015', 'Filed. His account of the 1944 uprising and the captain in the sewers is filed at LOR/003. Flag: he is described as a child in August 1944, which would make him about 100 in 2034.'),
  ('SYNPTCL/CHR/017', 'Filed. The origin of the name Ducks is not given in the passages read.'),
  ('SYNPTCL/CHR/018', 'Filed. Decide: surname left out of the entry.'),
  ('SYNPTCL/CHR/019', 'Filed. Interior passages are the archivist''s and are marked as such in the manuscript.'),
  ('SYNPTCL/CHR/021', 'Filed. Decide: the older profile name "Viktor" is taken as this officer.'),
  ('SYNPTCL/CHR/022', 'Filed in short form.'),
  ('SYNPTCL/CHR/023', 'Filed. Decide: the chapter number of the Interlude is to be confirmed at audit.'),
  ('SYNPTCL/CHR/024', 'Filed. Outcome not confirmed in the passages read.'),
  ('SYNPTCL/OBJ/001', 'Media: The Dendron tone, 180 Hz with a six second beat. To be produced for the site and the podcast.'),
  ('SYNPTCL/OBJ/002', 'Draft. The psychedelic use and the rituals are canon by David''s decision of 7 November 2026, and come from the older project note and the taxonomy. The manuscript does not yet say so. One line in Protocol 003, section 7, would bring the two into agreement.'),
  ('SYNPTCL/OBJ/003', 'Filed. Decide: binder three is not described in the passages read.'),
  ('SYNPTCL/OBJ/004', 'Filed in short form. Decide: a facsimile is planned for the web and book editions. The Entry will be expanded when the appendix is audited.'),
  ('SYNPTCL/OBJ/006', 'Filed. Decide: the larger holdings of photographs seen elsewhere in the manuscript (a steel drawer of prints in a museum) belong to another holder and are not filed here.'),
  ('SYNPTCL/LOR/001', 'Draft. The older project entry gave only a rationale for the name, and it is replaced by this one.
